    "answer_block": {
      "conditional_answer": "For two Gauteng adults bringing home R30,000 and R20,000 a month, combining households at 25 rather than 35 leaves about R3.972 million more combined household wealth at 75 in the average scenario, in constant 2026 rand. The direct living-cost saving is about R1.059 million. The larger gap comes from investing that earlier saving and from avoiding expensive negative balances.",
      "evidence_status": "modelled",
      "assumption_ids": [
        "GSX:HH-001:A01",
        "GSX:HH-001:A02",
        "GSX:HH-001:A03",
        "GSX:HH-001:A04"
      ],
      "result_ids": [
        "GSX:HH-001:R01",
        "GSX:HH-001:R02"
      ],
      "main_limitation": "This is a modelled scenario, not a forecast, and it is household wealth rather than each person's wealth. The manuscript keeps the relationship intact and invests the surplus. The advantage can disappear or reverse if the shared household costs almost as much as two homes, if the saving is consumed, or if separation costs exceed the accumulated benefit. Cohabitation here is a shared household, not a marriage result.",
      "sensitivity": "high"
    },
    "unresolved_questions": [
      "How do early cohabitation, delayed cohabitation, and separate households compare in a Gauteng lifetime scenario?"
    ],
    "entities": [
      "South Africa",
      "Gauteng",
      "cohabitation",
      "lifetime-wealth",
      "housing",
      "south-africa"
    ],
    "methods": [
      {
        "id": "GSX:HH-001:M01",
        "name": "Lifetime household-timing model",
        "model_class": "scenario model",
        "purpose": "The model follows two household paths from age 25 to 75 in constant 2026 rand. They differ in when they combine households. After 35 their housing arrangement matches, so the remaining gap comes from returns on the earlier balance or from the cost of a negative balance. Best, average, and worst cases change growth, returns, shocks, children, and housing.",
        "implementation_file": "research/source/expanded_lifetime_model.py"
      }
    ],
