    "answer_block": {
      "conditional_answer": "Among five packages that each close a hypothetical R150 billion annual ageing gap, the balanced transition has the lowest modelled welfare-loss index, 64.5. The low-visible-pain package, which leans on inflation, diffuse cuts, and continuing borrowing, scores 107.3 and leaves about R720 billion of emergency debt after ten years.",
      "evidence_status": "modelled",
      "assumption_ids": [
        "GSX:POP-005:A01",
        "GSX:POP-005:A02"
      ],
      "result_ids": [
        "GSX:POP-005:R01",
        "GSX:POP-005:R02"
      ],
      "main_limitation": "The R150 billion gap is a stress test, not a forecast of today's deficit. The welfare scores are internal model indexes, not percentages and not estimates of national wellbeing. The manuscript does not declare any package the single correct answer.",
      "sensitivity": "high"
    },
    "unresolved_questions": [
      "Which policy packages for closing an ageing-related fiscal deficit are examined for lower welfare loss?"
    ],
