    "answer_block": {
      "conditional_answer": "Every modelled path closes the first-year accounting gap of about R1.23 trillion. In the guardrailed case that ends in 2052, real output in 2080 is 1.2 percent below the no-shock path and the present value of lost output from 2050 to 2080 is R3.7 trillion.",
      "evidence_status": "modelled",
      "assumption_ids": [
        "GSX:POP-012:A01",
        "GSX:POP-012:A02"
      ],
      "result_ids": [
        "GSX:POP-012:R01"
      ],
      "main_limitation": "This is a counterfactual model, not a forecast and not legal advice. Closing the accounting gap does not create the doctors, food, energy, tax capacity or pension wealth that the shock removes.",
      "sensitivity": "high"
    },
    "unresolved_questions": [
      "How could emergency government measures introduced in 2050 alter the population system?"
    ],
