    "answer_block": {
      "conditional_answer": "If R1 million remains invested until age 100 at 4 percent above inflation, a living transfer at 35 becomes R12.80 million, an inheritance at 40 becomes R10.52 million, at 55 R5.84 million, at 70 R3.24 million, and at 85 R1.80 million, in constant 2026 rand.",
      "evidence_status": "modelled",
      "assumption_ids": [
        "GSX:POP-008:A01",
        "GSX:POP-008:A02"
      ],
      "result_ids": [
        "GSX:POP-008:R01",
        "GSX:POP-008:R02"
      ],
      "main_limitation": "These values exclude tax, fees, and consumption so that timing stays visible. The manuscript does not claim that 70 is today's average age of inheritance in South Africa. If the heir spends the money, or if returns differ by owner, the age-100 values do not apply.",
      "sensitivity": "high"
    },
    "unresolved_questions": [
      "What is the economic difference when inheritance arrives at 40, 55, 70, or 85?"
    ],
