    "answer_block": {
      "conditional_answer": "For matched descendants, the central scenario produces median marketable net worth after forty years of R3.67 million with a titled township home and R5.24 million with a middle-value suburban home. The difference is R1.57 million, in constant 2024 rand.",
      "evidence_status": "modelled",
      "assumption_ids": [
        "GSX:WPL-001:A01"
      ],
      "result_ids": [
        "GSX:WPL-001:R01",
        "GSX:WPL-001:R02"
      ],
      "main_limitation": "These are scenarios, not forecasts and not estimates for a racial group. The comparison shows that inherited property conditions can be large enough to matter. It does not show what share of the national wealth gap that mechanism causes.",
      "sensitivity": "high"
    },
    "unresolved_questions": [
      "How does South Africa's unequal property geography continue to compound into differences in wealth?"
    ],
