    "answer_block": {
      "conditional_answer": "In the central catch-up case, a weighted 6.7 percent equipment share produces about US$262 billion of South African equipment sales over twenty-five years and about US$201 billion of value retained in South Africa.",
      "evidence_status": "modelled",
      "assumption_ids": [
        "GSX:IND-005:A01",
        "GSX:IND-005:A02",
        "GSX:IND-005:A03"
      ],
      "result_ids": [
        "GSX:IND-005:R01",
        "GSX:IND-005:R02"
      ],
      "main_limitation": "The paths are scenarios, not forecasts, and the retained value cannot be added mechanically to a GDP forecast. Some of this activity already exists. The result is a scale test of a selected machinery and service position, not a claim that South Africa should make every final product.",
      "sensitivity": "high"
    },
    "unresolved_questions": [
      "What equipment, capabilities, and supplier networks sit behind durable industrialisation?"
    ],
