    "answer_block": {
      "conditional_answer": "In the central middle-salary Johannesburg scenario, living in the family home and delaying a car purchase for three years creates R602,000 more modelled net capital at age 25, and R3.32 million more modelled wealth at age 60, than moving out and financing a car immediately. The age-60 figure holds when the gap is preserved on the manuscript's common post-25 path.",
      "evidence_status": "modelled",
      "assumption_ids": [
        "GSX:HH-002:A01",
        "GSX:HH-002:A02",
        "GSX:HH-002:A03",
        "GSX:HH-002:A04",
        "GSX:HH-002:A05",
        "GSX:HH-002:A06",
        "GSX:HH-002:A07"
      ],
      "result_ids": [
        "GSX:HH-002:R01",
        "GSX:HH-002:R02",
        "GSX:HH-002:R03",
        "GSX:HH-002:R04"
      ],
      "main_limitation": "This is a modelled counterfactual for one representative worker, not a forecast and not a statement that every graduate can or should live at home. The age-60 level includes a common 10% retirement-saving path. The manuscript treats the gap between strategies as the robust quantity, and the level as a scale illustration.",
      "sensitivity": "high"
    },
    "unresolved_questions": [
      "How can delaying rent and car ownership at the start of a career alter lifetime wealth?"
    ],
