        "id": "GSX:HH-002:M01",
        "name": "First-three-years household budget",
        "model_class": "scenario model",
        "purpose": "The model follows the first 36 months in monthly detail, covering salary, tax, household contribution, housing, transport, moving costs, and vehicle finance. At month 36 every strategy has moved out and acquired the modelled car. A common salary, saving, and return path then carries the age-25 gap forward. Differences at age 60 are attributed to the first three years.",
