    "answer_block": {
      "conditional_answer": "The manuscript's first expansion is a qualified 30,000-tonne-a-year HPMSM platform linked to firm offtake, with partner-led cathode production and a later, conditional 4 to 6 GWh cell plant.",
      "evidence_status": "modelled",
      "assumption_ids": [
        "GSX:IND-003:A01",
        "GSX:IND-003:A02"
      ],
      "result_ids": [
        "GSX:IND-003:R01"
      ],
      "main_limitation": "Cell and pack revenue is not created by manganese alone. Most of it pays for other materials, components, capital and distribution. The tower values must not be added together.",
      "sensitivity": "moderate"
    },
    "unresolved_questions": [
      "What route runs from manganese extraction to higher-value battery production?"
    ],
