    "answer_block": {
      "conditional_answer": "Under the central rule, the fund reaches about R586 billion by 2060 and transfers about R16 billion that year, rising to R1.48 trillion and R43 billion by 2125, in constant 2026 rand.",
      "evidence_status": "modelled",
      "assumption_ids": [
        "GSX:IND-006:A01",
        "GSX:IND-006:A02",
        "GSX:IND-006:A03"
      ],
      "result_ids": [
        "GSX:IND-006:R01",
        "GSX:IND-006:R02"
      ],
      "main_limitation": "A fund does not create a fiscal surplus. If the deposit is matched by new borrowing at a higher cost, the country has a leveraged portfolio rather than national savings. The transfer is a marginal public income, not a self-financing welfare state.",
      "sensitivity": "high"
    },
    "unresolved_questions": [
      "What fiscal architecture converts exhaustible mineral resources into permanent public wealth?"
    ],
