        "id": "GSX:IND-006:M01",
        "name": "Mineral savings-fund paths",
        "model_class": "fund accumulation scenario",
        "purpose": "Royalties, windfall mining tax and dividends are deposited by rule into a separate fund. The central case waits 15 years and then withdraws 3 percent of the trailing five-year fund value.",
