    "answer_block": {
      "conditional_answer": "Demographic pressure, in this synthesis, is rarely a shortage of people in the abstract. It is a failure of timing, matching and institutions. Income can arrive after it is useful, workers can exist outside the jobs that need them, homes can stand in the wrong places, and reform can begin after the cheaper options have expired.",
      "evidence_status": "modelled",
      "assumption_ids": [
        "GSX:POP-011:A01",
        "GSX:POP-011:A02"
      ],
      "result_ids": [
        "GSX:POP-011:R01"
      ],
      "main_limitation": "This is a structural reading of ten hypothetical models, not a new forecast and not a single national estimate. The magnitudes belong to the individual studies. A smaller population can still need more homes, and higher productivity can preserve GDP while hospitals remain understaffed.",
      "sensitivity": "moderate"
    },
    "unresolved_questions": [
      "How do the population studies connect as one policy system?"
    ],
