    "answer_block": {
      "conditional_answer": "In the average run, the median cost of one permanently additional birth ranges from about R720,000 for free childcare to R4.18 million for a parent tax exemption. The targeted family package costs about R780,000 per added birth and produces nearly 99,000 additional births per million prospective households. A cash top-up costs about R1.76 million per added birth and produces only about 12,000.",
      "evidence_status": "modelled",
      "assumption_ids": [
        "GSX:POP-006:A01",
        "GSX:POP-006:A02"
      ],
      "result_ids": [
        "GSX:POP-006:R01"
      ],
      "main_limitation": "The largest payment is not the cheapest birth. A programme can pay households that would have had the child anyway, or it can only move the timing. The cost figures are medians from a stylised model, with wide 10th-to-90th percentile ranges in the manuscript.",
      "sensitivity": "high"
    },
    "unresolved_questions": [
      "When does fertility support become cheaper than financing demographic decline?"
    ],
    "entities": [
      "South Africa",
      "population-decline",
      "fiscal-policy",
      "south-africa"
    ],
    "methods": [
      {
        "id": "GSX:POP-006:M01",
        "name": "Additional-birth cost model",
        "model_class": "scenario model",
        "purpose": "The model separates births that would have happened, births that are brought forward, and births that permanently add to completed family size. Programme cost is judged against the permanently additional group and against the future fiscal value of that person.",
        "implementation_file": "research/source/price_of_another_child_model.py"
      }
    ],
