    "answer_block": {
      "conditional_answer": "In the central mixed portfolio, R225 billion of public industrial capital mobilises R506 billion of gross investment, 2.25 times the public envelope. After deductions, R383 billion remains operating, 1.70 times the envelope.",
      "evidence_status": "modelled",
      "assumption_ids": [
        "GSX:SRD-004:A01",
        "GSX:SRD-004:A02",
        "GSX:SRD-004:A03"
      ],
      "result_ids": [
        "GSX:SRD-004:R01",
        "GSX:SRD-004:R02"
      ],
      "main_limitation": "A multiplier is a description of a capital stack, not money created. Guarantees can show a high cash multiple while leaving the downside with the state. The multiples are not observed South African averages.",
      "sensitivity": "high"
    },
    "unresolved_questions": [
      "When do state-financed productive assets generate durable economic capacity?"
    ],
