        "id": "P01",
        "name": "Programme envelope",
        "symbol": "see the manuscript",
        "description": "The envelope from 2020/21 through the 2026/27 allocation is R225.8 billion in nominal rand, about R253.5 billion in constant 2026 purchasing power. Later years include a revised estimate and a voted allocation, not only cash already spent.",
