    "answer_block": {
      "conditional_answer": "In the average case, a smaller resident workforce can still coincide with real GDP at an index of 151, because output per worker rises about 57 percent. The total workforce ends at 11.60 million after 75,000 young immigrants a year and 700,000 additional older workers.",
      "evidence_status": "modelled",
      "assumption_ids": [
        "GSX:POP-010:A01",
        "GSX:POP-010:A02"
      ],
      "result_ids": [
        "GSX:POP-010:R01"
      ],
      "main_limitation": "This is a hypothetical scale, not a forecast of South Africa's labour market. The 75,000-person inflow is below the roughly 90,000 a year that would hold contributor headcount at 12 million. Early immigrant cohorts also retire: 480,000 are retirees by 2076.",
      "sensitivity": "high"
    },
    "unresolved_questions": [
      "Can automation, productivity, and immigration substitute for missing workers?"
    ],
