    "figures": [
      {
        "id": "F01",
        "title": "Endowment gap",
        "caption": "Figure 1. The 2025 Critical Minerals and Metals Strategy cites reserve-share estimates of 88 per cent for PGMs, 80 per cent for manganese and 32 per cent for vanadium. USGS estimates for 2024 mined production are lower and measure a different thing: about 70, 40 and 7 per cent respectively. The gap is the first warning against confusing geology with industrial power.",
        "alt_text": "Endowment gap",
        "image_file": "C:/Users/Deriv/Desktop/GreyScienx/research/source/critical-minerals-industrial-complex/assets/endowment-gap.png",
        "data_file": "research/source/critical-minerals-industrial-complex/model_results.json",
        "result_ids": [
          "GSX:IND-001:R01"
        ],
        "source_ids": [
          "GSX:IND-001:PDF"
        ]
      },
      {
        "id": "F02",
        "title": "Integrated value chains",
        "caption": "Figure 2. The three chains are not separate empires. They can share electricity, water, chemical reagents, laboratories, engineering suppliers, industrial parks, logistics, testing and recycling. Coral marks the model's strongest initial localisation targets; grey identifies stages better approached through partnership, gradual learning or imports.",
        "alt_text": "Integrated value chains",
        "image_file": "C:/Users/Deriv/Desktop/GreyScienx/research/source/critical-minerals-industrial-complex/assets/integrated-system-map.png",
        "data_file": "research/source/critical-minerals-industrial-complex/model_results.json",
        "result_ids": [
          "GSX:IND-001:R01"
        ],
        "source_ids": [
          "GSX:IND-001:PDF"
        ]
      },
      {
        "id": "F03",
        "title": "Readiness heatmap",
        "caption": "Figure 3. Armchair scores make judgement visible. They are not empirical rankings. High-purity manganese sulphate, catalyst materials, PGM recycling, vanadium electrolyte and VRFB integration combine relatively strong readiness with high strategic value. Cells and complete stacks have high upside but low immediate readiness.",
        "alt_text": "Readiness heatmap",
        "image_file": "C:/Users/Deriv/Desktop/GreyScienx/research/source/critical-minerals-industrial-complex/assets/readiness-heatmap.png",
        "data_file": "research/source/critical-minerals-industrial-complex/model_results.json",
        "result_ids": [
          "GSX:IND-001:R01"
        ],
        "source_ids": [
          "GSX:IND-001:PDF"
        ]
      },
      {
        "id": "F04",
        "title": "Priority frontier",
        "caption": "Figure 4. Activities in the upper-right can be built or scaled. Upper-left activities deserve partnership or licensing because the prize is high but readiness is incomplete. The lower quadrants call for selective localisation or a pilot rather than a national-scale bet.",
        "alt_text": "Priority frontier",
        "image_file": "C:/Users/Deriv/Desktop/GreyScienx/research/source/critical-minerals-industrial-complex/assets/priority-frontier.png",
        "data_file": "research/source/critical-minerals-industrial-complex/model_results.json",
        "result_ids": [
          "GSX:IND-001:R01"
        ],
        "source_ids": [
          "GSX:IND-001:PDF"
        ]
      },
      {
        "id": "F05",
        "title": "Make partner import",
        "caption": "Figure 5. The recommendation is intentionally mixed. Domestic production, partnerships and imports are tools inside one strategy. Learning and circular services prevent today's import from becoming permanent dependence.",
        "alt_text": "Make partner import",
        "image_file": "C:/Users/Deriv/Desktop/GreyScienx/research/source/critical-minerals-industrial-complex/assets/make-partner-import.png",
        "data_file": "research/source/critical-minerals-industrial-complex/model_results.json",
        "result_ids": [
          "GSX:IND-001:R01"
        ],
        "source_ids": [
          "GSX:IND-001:PDF"
        ]
      },
      {
        "id": "F06",
        "title": "Capture ladder",
        "caption": "Figure 6. The focused scenario does not require complete local production. It more than doubles the manganese chain's retained-value share in the model and lifts the portfolio to about two-thirds by targeting advanced materials, integration and services.",
        "alt_text": "Capture ladder",
        "image_file": "C:/Users/Deriv/Desktop/GreyScienx/research/source/critical-minerals-industrial-complex/assets/capture-ladder.png",
        "data_file": "research/source/critical-minerals-industrial-complex/model_results.json",
        "result_ids": [
          "GSX:IND-001:R01"
        ],
        "source_ids": [
          "GSX:IND-001:PDF"
        ]
      },
      {
        "id": "F07",
        "title": "Stage capture",
        "caption": "Figure 7. In the focused case, resource extraction is overwhelmingly local. Core components remain the weakest stage. This is not automatically a failure: importing a specialised component can enable competitive local systems while capability is built.",
        "alt_text": "Stage capture",
        "image_file": "C:/Users/Deriv/Desktop/GreyScienx/research/source/critical-minerals-industrial-complex/assets/stage-capture.png",
        "data_file": "research/source/critical-minerals-industrial-complex/model_results.json",
        "result_ids": [
          "GSX:IND-001:R01"
        ],
        "source_ids": [
          "GSX:IND-001:PDF"
        ]
      },
      {
        "id": "F08",
        "title": "Capital portfolio",
        "caption": "Figure 8. Illustrative allocation of R253.5 billion. The largest line is shared power, water, rail and port infrastructure. R&D, testing, supplier finance and a closure reserve are part of the productive system rather than overhead to be minimised.",
        "alt_text": "Capital portfolio",
        "image_file": "C:/Users/Deriv/Desktop/GreyScienx/research/source/critical-minerals-industrial-complex/assets/capital-portfolio.png",
        "data_file": "research/source/critical-minerals-industrial-complex/model_results.json",
        "result_ids": [
          "GSX:IND-001:R01"
        ],
        "source_ids": [
          "GSX:IND-001:PDF"
        ]
      },
      {
        "id": "F09",
        "title": "Bottlenecks",
        "caption": "Figure 9. Indicative criticality scores. Reliable competitively priced power, bankable offtake and project governance rank above mineral availability because failure in any one can strand an otherwise sound plant.",
        "alt_text": "Bottlenecks",
        "image_file": "C:/Users/Deriv/Desktop/GreyScienx/research/source/critical-minerals-industrial-complex/assets/bottlenecks.png",
        "data_file": "research/source/critical-minerals-industrial-complex/model_results.json",
        "result_ids": [
          "GSX:IND-001:R01"
        ],
        "source_ids": [
          "GSX:IND-001:PDF"
        ]
      },
      {
        "id": "F10",
        "title": "Policy choice",
        "caption": "Figure 10. Nominal local content is reduced by an assumed viability factor reflecting plant utilisation, cost competitiveness and market access. Forced autarky retains less realised value than disciplined partnership even though its stated local-content ambition is high.",
        "alt_text": "Policy choice",
        "image_file": "C:/Users/Deriv/Desktop/GreyScienx/research/source/critical-minerals-industrial-complex/assets/policy-choice.png",
        "data_file": "research/source/critical-minerals-industrial-complex/model_results.json",
        "result_ids": [
          "GSX:IND-001:R01"
        ],
        "source_ids": [
          "GSX:IND-001:PDF"
        ]
      },
      {
        "id": "F11",
        "title": "Sequence",
        "caption": "Figure 11. Illustrative sequence, not a forecast. Shared utilities and offtake begin first. Advanced materials and catalysts scale next. Cathodes, membrane-electrode assemblies and stack materials deepen through partnership. Selective cells and complete stacks follow only after markets and capabilities are demonstrated.",
        "alt_text": "Sequence",
        "image_file": "C:/Users/Deriv/Desktop/GreyScienx/research/source/critical-minerals-industrial-complex/assets/sequence.png",
        "data_file": "research/source/critical-minerals-industrial-complex/model_results.json",
        "result_ids": [
          "GSX:IND-001:R01"
        ],
        "source_ids": [
          "GSX:IND-001:PDF"
        ]
      }
    ],
