    "answer_block": {
      "conditional_answer": "Withholding the SRD envelope has a central explicit welfare cost of R426.9 billion in welfare-equivalent 2026 rand, about R1.68 of social cost for every R1 withheld. The scenario range is R237 billion to R743 billion.",
      "evidence_status": "modelled",
      "assumption_ids": [
        "GSX:SRD-002:A01",
        "GSX:SRD-002:A02",
        "GSX:SRD-002:A03"
      ],
      "result_ids": [
        "GSX:SRD-002:R01"
      ],
      "main_limitation": "This is not a Treasury invoice, a forecast or a confidence interval. Crime, unrest and household dissolution are left outside the priced total. The central case is an analytical benchmark.",
      "sensitivity": "high"
    },
    "unresolved_questions": [
      "What poverty, consumption, and social costs does the industrialisation counterfactual leave out when the grant is not paid?"
    ],
