        "purpose": "The model follows six work histories that share an earning schedule and differ in employment, formality, saving, and effective tax contribution. Private assets build until 60 and are then drawn through age 100. The fiscal comparison holds healthcare costs equal so the gap comes from taxes and cash transfers.",
