        "title": "Private retirement wealth paths",
        "caption": "Figure 1. The same retirement age produces radically different asset peaks. Every path reaches approximately zero at 100 because each pension is calibrated to consume its own available wealth across retirement.",
        "alt_text": "Private retirement wealth paths",
