        "title": "Retirement income ladder",
        "caption": "Figure 2. Black is private pension income and coral is the simplified grant. The dotted line is 60 percent of the full benchmark wage at retirement. Public support cushions low income but cannot reconstruct the missing pension.",
        "alt_text": "Retirement income ladder",
