        "id": "F03",
        "title": "Delayed entry catch-up rates",
        "caption": "Figure 3. At a 3 percent real return, entry at 30 requires saving about 24 percent of salary, entry at 35 about 33 percent, entry at 40 about 51 percent and entry at 45 about 86 percent.",
        "alt_text": "Delayed entry catch-up rates",
        "image_file": "C:/Users/Deriv/Desktop/GreyScienx/research/source/unemployment-pension/assets/delayed-entry-catchup.png",
