        "name": "Two retirement machines",
        "model_class": "scenario model",
        "purpose": "One lens is a funded individual account. The other is a pay-as-you-go public pension aged for 260 years so each fertility and longevity pair can settle. The manuscript uses them as lenses. They are not a literal replica of one South African institution.",
